import subprocess
import json
import time
import sys
import re

AUTH = "gk_live_79414cc5d34021a6.f48b009c9ed9470d05fbec8f4ef919f4d657e7a15d91347a"
CLIENT_ID = "cli_a1b2c3d4e5f6789012345678abcdef90"
BASE_URL = "https://openapi.biji.com/open/api/v1/resource"

KB_CHIP = "9YeBam0m"
KB_OC = "G0P1Z51J"
KB_FAMILY = "EJX1r7bn"

SKIP_PREFIXES = ["🌱发芽日报", "🌱发芽报告", "📦每日备份报告", "每日复盘", "🦐发芽报告", "OpenClaw每日备份报告"]

CHIP_KW = ["芯片", "半导体", "ecdn", "ear", "出口管制", "封装", "测试", "良率", "供应商", "质量"]
OC_KW = ["openclaw", "agent", "skill", "chatgpt", "deepseek", "claude", "大模型", "AI工具", "提示词"]
FAMILY_KW = ["兮兮", "中考", "英语", "语文", "数学", "物理", "化学", "生物", "地理", "学习", "教育", "成绩", "考试", "错题", "青春期", "亲子"]

MAX_API = 500
MAX_ADD = 50

def curl_get(url):
    result = subprocess.run(
        ["curl", "-s", url, 
         "-H", f"Authorization: {AUTH}",
         "-H", f"X-Client-ID: {CLIENT_ID}"],
        capture_output=True, text=True
    )
    return result.stdout

def curl_post(url, payload):
    result = subprocess.run(
        ["curl", "-s", "-X", "POST", url,
         "-H", f"Authorization: {AUTH}",
         "-H", f"X-Client-ID: {CLIENT_ID}",
         "-H", "Content-Type: application/json",
         "-d", json.dumps(payload)],
        capture_output=True, text=True
    )
    return result.stdout

def classify(title, content):
    text = (title + " " + (content or "")[:500]).lower()
    cats = []
    if any(kw.lower() in text for kw in CHIP_KW):
        cats.append("chip")
    if any(kw.lower() in text for kw in OC_KW):
        cats.append("oc")
    if any(kw in text for kw in FAMILY_KW):
        cats.append("family")
    return cats

def should_skip(title):
    for p in SKIP_PREFIXES:
        if title.startswith(p):
            return True
    return False

def batch_add(topic_id, note_ids):
    """返回成功添加的数量"""
    if not note_ids:
        return 0
    resp = curl_post(f"{BASE_URL}/knowledge/note/batch-add", {
        "topic_id": topic_id,
        "note_ids": note_ids
    })
    try:
        d = json.loads(resp)
        return d.get("data", {}).get("success_count", 0)
    except:
        print(f"    batch_add error: {resp[:200]}")
        return 0

def main():
    cursor = "1873611189678932616"
    stop_cursor = "1850511050601039697"

    scan_count = 0
    add_count = 0
    api_count = 0

    chip_buf = []
    oc_buf = []
    family_buf = []

    KB_MAP = {"chip": KB_CHIP, "oc": KB_OC, "family": KB_FAMILY}
    BUFS = {"chip": chip_buf, "oc": oc_buf, "family": family_buf}

    def flush_cat(cat):
        nonlocal add_count
        buf = BUFS[cat]
        if not buf:
            return
        topic_id = KB_MAP[cat]
        success = batch_add(topic_id, buf)
        print(f"  [{cat}] batch_add: {len(buf)} notes, success={success}")
        add_count += success
        buf.clear()

    def maybe_flush():
        for cat in ["chip", "oc", "family"]:
            if len(BUFS[cat]) >= 20:
                flush_cat(cat)

    print(f"[{time.strftime('%H:%M:%S')}] P4 迁移开始")
    print(f"  cursor: {cursor} -> {stop_cursor}")

    page = 0
    while api_count < MAX_API:
        page += 1
        url = f"{BASE_URL}/note/list?since_id={cursor}"
        resp = curl_get(url)
        api_count += 1

        try:
            d = json.loads(resp)
        except:
            print(f"  JSON parse error, resp: {resp[:200]}")
            break

        data = d.get("data", {})
        notes = data.get("notes", [])
        has_more = data.get("has_more", False)

        if not notes:
            print("  无笔记，停止")
            break

        # 下一页 cursor = 最后一条笔记的 id
        next_cursor = str(notes[-1].get("id", ""))
        if not next_cursor or next_cursor == cursor:
            print("  cursor 不变，停止")
            break

        cursor = next_cursor

        print(f"[{time.strftime('%H:%M:%S')}] page={page} cursor={cursor} notes={len(notes)} api={api_count}")

        # 检查终止
        if int(cursor) < int(stop_cursor):
            print(f"  到达终止 cursor {stop_cursor}，停止")
            break

        for n in notes:
            note_id = str(n.get("id", ""))
            title = (n.get("title") or "")[:80]
            ntype = n.get("note_type", "")
            topics = [t.get("topic_id", "") for t in n.get("topics", [])]

            if ntype != "plain_text":
                continue
            if should_skip(title):
                continue
            if not title.strip():
                continue

            scan_count += 1

            # 获取详情确认内容
            detail_resp = curl_get(f"{BASE_URL}/note/detail?id={note_id}")
            api_count += 1

            content = ""
            try:
                dd = json.loads(detail_resp)
                dd_data = dd.get("data", {})
                if isinstance(dd_data, dict):
                    note_detail = dd_data.get("note", dd_data)
                else:
                    note_detail = {}
                content = note_detail.get("content", "") or ""
            except:
                content = ""

            cats = classify(title, content)

            if cats:
                for cat in cats:
                    if add_count >= MAX_ADD:
                        print(f"  达每日上限 {MAX_ADD}，停止")
                        # flush remaining
                        for c in ["chip", "oc", "family"]:
                            if BUFS[c]:
                                flush_cat(c)
                        print(f"  >>> 扫描: {scan_count} 入库: {add_count} API: {api_count}")
                        print_status(scan_count, add_count, api_count, cursor, stop_cursor)
                        return
                    BUFS[cat].append(note_id)
                    maybe_flush()

            if api_count >= MAX_API - 30:
                print(f"  API配额警告: {api_count}/{MAX_API}")
                if api_count >= MAX_API:
                    break

        if api_count >= MAX_API:
            break

    # final flush
    for cat in ["chip", "oc", "family"]:
        flush_cat(cat)

    print(f"\n========== P4 完成 ==========")
    print(f"扫描: {scan_count} | 入库: {add_count} | API: {api_count} | cursor: {cursor}")
    print("=============================")
    print_status(scan_count, add_count, api_count, cursor, stop_cursor)

def print_status(scan, add, api, cursor, stop):
    content = f"""# Get笔记 P4 任务状态

## 执行时间
{time.strftime('%Y-%m-%d %H:%M:%S')}

## 统计
- 扫描笔记数: {scan}
- 入库笔记数: {add}
- API调用数: {api}

## Cursor
- 起始: 1873611189678932616
- 终止: {stop}
- 最终: {cursor}

## 状态
P4 迁移完成
"""
    with open("/tmp/getnote_p4_status.md", "w") as f:
        f.write(content)
    print("状态文件已写入 /tmp/getnote_p4_status.md")

if __name__ == "__main__":
    main()

